// Turns each search (from the form or a Competitors row) into one Apify request.
// A search can be a Meta Ad Library URL, a Facebook page URL, a numeric page ID, or a keyword.
const DEFAULT_COUNTRY = 'US';
const DEFAULT_MAX_ADS = 20;
const MAX_ADS_LIMIT = 100;

const out = [];
for (const [index, item] of $input.all().entries()) {
  const j = item.json;
  const search = String(j.search ?? '').trim();
  if (!search) continue;

  let country = String(j.country ?? '').trim().toUpperCase();
  if (!/^([A-Z]{2}|ALL)$/.test(country)) country = DEFAULT_COUNTRY;

  let maxAds = parseInt(j.max_ads, 10);
  if (!(maxAds > 0)) maxAds = DEFAULT_MAX_ADS;
  maxAds = Math.min(maxAds, MAX_ADS_LIMIT);

  const activeOnly = !/^(no|n|false|0)$/i.test(String(j.active_only ?? '').trim());
  const status = activeOnly ? 'active' : 'all';
  const withScheme = (s) => (/^https?:\/\//i.test(s) ? s : 'https://' + s);

  let searchType;
  let startUrl;
  if (/facebook\.com\/ads\/library/i.test(search)) {
    searchType = 'Ad Library URL';
    startUrl = withScheme(search);
  } else if (/^(https?:\/\/)?([\w-]+\.)*(facebook|fb)\.com\//i.test(search)) {
    searchType = 'Facebook page';
    startUrl = withScheme(search);
  } else if (/^\d{6,}$/.test(search)) {
    searchType = 'Facebook page ID';
    startUrl = 'https://www.facebook.com/ads/library/?active_status=' + status +
      '&ad_type=all&country=' + country + '&is_targeted_country=false&media_type=all' +
      '&search_type=page&view_all_page_id=' + search;
  } else {
    searchType = 'Keyword';
    startUrl = 'https://www.facebook.com/ads/library/?active_status=' + status +
      '&ad_type=all&country=' + country + '&is_targeted_country=false&media_type=all' +
      '&q=' + encodeURIComponent(search) + '&search_type=keyword_unordered';
  }

  out.push({
    json: {
      search,
      label: String(j.label ?? '').trim() || search,
      search_type: searchType,
      country,
      max_ads: maxAds,
      active_only: activeOnly,
      start_url: startUrl,
      apify_input: {
        startUrls: [{ url: startUrl }],
        resultsLimit: maxAds,
        activeStatus: activeOnly ? 'active' : '',
      },
    },
    pairedItem: { item: index },
  });
}

return out;

// Turns the Apify Facebook Ads Scraper output into one clean record per ad.
const items = $input.all();
const arr = (v) => (Array.isArray(v) ? v : []);
const str = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const isTemplate = (s) => /\{\{\s*product\./i.test(s);
const firstText = (...vals) => {
  for (const v of vals) {
    const s = str(typeof v === 'object' && v !== null ? v.text : v);
    if (s && !isTemplate(s)) return s;
  }
  return '';
};
const pick = (o, ...keys) => {
  for (const k of keys) if (o && o[k]) return str(o[k]);
  return '';
};
const toMs = (unix, iso) => {
  if (unix) return Number(unix) * (Number(unix) < 1e12 ? 1000 : 1);
  const t = Date.parse(iso || '');
  return Number.isNaN(t) ? null : t;
};
const day = (ms) => (ms ? new Date(ms).toISOString().slice(0, 10) : '');

const ads = [];
const errors = [];
const seen = new Set();

for (const [i, item] of items.entries()) {
  const j = item.json;
  let src = {};
  try {
    src = $('Build Ad Library URL').itemMatching(i).json;
  } catch (e) {
    src = $('Build Ad Library URL').all().map((x) => x.json).find((x) => x.start_url === j.inputUrl) ?? {};
  }

  const adId = str(j.adArchiveID ?? j.adArchiveId ?? j.ad_archive_id);
  if (!adId) {
    if (j.error) {
      const msg = typeof j.error === 'object' ? (j.error.message || JSON.stringify(j.error)) : j.error;
      errors.push(`${src.label || src.search || 'search'}: ${str(msg).slice(0, 300)}`);
    }
    continue;
  }

  const collationId = str(j.collationId ?? j.collationID ?? j.collation_id);
  const key = collationId ? 'c:' + collationId : adId;
  if (seen.has(key)) continue;
  seen.add(key);

  const snap = j.snapshot ?? {};
  const images = arr(snap.images);
  const videos = arr(snap.videos);
  const cards = arr(snap.cards);
  const card = cards[0] ?? {};
  const displayFormat = str(snap.displayFormat ?? snap.display_format).toUpperCase();

  let format;
  if (displayFormat === 'VIDEO') format = 'video';
  else if (displayFormat === 'DCO' || displayFormat === 'DPA') format = 'dynamic';
  else if (displayFormat === 'CAROUSEL' || cards.length > 1) format = 'carousel';
  else if (displayFormat === 'IMAGE' || images.length) format = 'image';
  else if (videos.length) format = 'video';
  else if (cards.length) format = pick(card, 'videoHdUrl', 'videoSdUrl', 'video_hd_url') ? 'video' : 'image';
  else format = displayFormat ? displayFormat.toLowerCase() : 'text';

  const image = images[0] ?? {};
  const video = videos[0] ?? {};
  const creativeUrl =
    pick(image, 'originalImageUrl', 'resizedImageUrl', 'original_image_url', 'resized_image_url') ||
    pick(video, 'videoPreviewImageUrl', 'video_preview_image_url') ||
    pick(card, 'originalImageUrl', 'resizedImageUrl', 'videoPreviewImageUrl',
      'original_image_url', 'resized_image_url', 'video_preview_image_url');
  const videoUrl = pick(video, 'videoHdUrl', 'videoSdUrl', 'video_hd_url', 'video_sd_url') ||
    pick(card, 'videoHdUrl', 'videoSdUrl', 'video_hd_url', 'video_sd_url');
  const isVideo = format === 'video' || !!videoUrl;

  const startMs = toMs(j.startDate, j.startDateFormatted);
  const endMs = toMs(j.endDate, j.endDateFormatted);
  const active = j.isActive === true || str(j.isActive).toLowerCase() === 'true';
  const until = active || !endMs ? Date.now() : endMs;
  const daysRunning = startMs ? Math.max(1, Math.round((until - startMs) / 86400000)) : 0;

  const pageName = str(j.pageName ?? snap.pageName ?? snap.page_name);
  const headline = firstText(snap.title, card.title);
  const body = firstText(snap.body, card.body);
  const cta = firstText(snap.ctaText, card.ctaText);
  const linkUrl = firstText(snap.linkUrl, card.linkUrl);
  const linkDescription = firstText(snap.linkDescription, card.linkDescription);
  const platforms = arr(j.publisherPlatform ?? j.publisherPlatforms)
    .map((p) => str(p).toLowerCase().replace(/_/g, ' '))
    .join(', ');
  const variants = Number(j.collationCount ?? j.collation_count) || 1;

  let analysisBasis = 'ad copy only';
  let creativeNote = 'No image is available for this ad. Analyze it from the copy and details only.';
  if (creativeUrl) {
    if (isVideo) {
      analysisBasis = 'video preview image and ad copy';
      creativeNote = "The attached image is the video's preview frame. You cannot watch the video, so base the format notes on this frame and the copy.";
    } else if (format === 'carousel' || format === 'dynamic') {
      analysisBasis = 'first card image and ad copy';
      creativeNote = 'The attached image is the first card of a ' + format + ' ad.';
    } else {
      analysisBasis = 'image and ad copy';
      creativeNote = "The attached image is the ad's creative.";
    }
  }

  const adDetails = [
    `Advertiser: ${pageName || 'Unknown'}`,
    `Found by searching: ${src.label || src.search || ''}`,
    `Format: ${format}`,
    `Status: ${active ? 'active' : 'inactive'}, running for ${daysRunning} days${startMs ? ' (since ' + day(startMs) + ')' : ''}`,
    `Platforms: ${platforms || 'Not listed'}`,
    `Ads using this creative: ${variants}`,
    '',
    `Headline: ${headline || 'None'}`,
    'Primary text:',
    body || 'None',
    '',
    `Call to action button: ${cta || 'None'}`,
    `Link: ${linkUrl || 'None'}`,
    `Link description: ${linkDescription || 'None'}`,
  ].join('\n');

  ads.push({
    json: {
      ad_id: adId,
      collation_id: collationId,
      search: src.label || src.search || '',
      page_name: pageName,
      page_url: str(snap.pageProfileUri ?? snap.page_profile_uri),
      ad_library_url: 'https://www.facebook.com/ads/library/?id=' + adId,
      status: active ? 'active' : 'inactive',
      start_date: day(startMs),
      days_running: daysRunning,
      platforms,
      format,
      variants,
      headline,
      body,
      cta,
      link_url: linkUrl,
      creative_url: creativeUrl,
      video_url: videoUrl,
      analysis_basis: analysisBasis,
      creative_note: creativeNote,
      ad_details: adDetails,
    },
  });
}

if (!ads.length && errors.length) {
  throw new Error('Apify did not return any ads. ' + errors.join(' | '));
}

return ads;

// Keeps only ads that are not in the Ads tab yet, longest-running first,
// and caps how many are analyzed in one run.
const MAX_ADS_TO_ANALYZE = 30;

const logged = new Set();
const clean = (v) => String(v ?? '').trim().replace(/^'/, '');
for (const row of $input.all()) {
  const adId = clean(row.json.ad_id);
  const collationId = clean(row.json.collation_id);
  const fromUrl = clean(row.json.ad_library_url).match(/[?&]id=(\d+)/);
  if (adId) logged.add(adId);
  if (fromUrl) logged.add(fromUrl[1]);
  if (collationId) logged.add('c:' + collationId);
}

const fresh = $('Normalize Ads')
  .all()
  .map((item) => item.json)
  .filter((ad) => !logged.has(ad.ad_id) && !(ad.collation_id && logged.has('c:' + ad.collation_id)));

// Ads that have run the longest are the ones most likely to be profitable.
fresh.sort((a, b) => b.days_running - a.days_running);

return fresh.slice(0, MAX_ADS_TO_ANALYZE).map((json) => ({ json }));

