{
  "type": "object",
  "properties": {
    "hook": {
      "type": "string",
      "description": "The opening line or visual that stops the scroll, quoted or described"
    },
    "angle": {
      "type": "string",
      "description": "The core marketing angle, such as a pain point, social proof, a transformation, a comparison, urgency, or curiosity"
