    },
    "target_audience": {
      "type": "string",
      "description": "Who the ad is written for"
    },
    "emotional_triggers": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The emotions or motivations the ad uses"
    },
    "format_notes": {
      "type": "string",
      "description": "How the creative is built: visual style, text on the image, people, product shots, colors, and layout"
    },
    "why_it_works": {
      "type": "string",
      "description": "Two or three sentences on why the ad is likely effective, or why it is weak"
    },
    "score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Overall strength from 1 to 10"
    },
    "ideas_to_adapt": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 3,
      "maxItems": 3,
      "description": "Three ideas another brand could test based on this ad"
    }
  },
  "required": [
    "hook",
    "angle",
    "offer",
    "call_to_action",
    "target_audience",
    "emotional_triggers",
    "format_notes",
    "why_it_works",
    "score",
    "ideas_to_adapt"
  ]
}

