// Combines the ad details with the AI analysis into one row per ad for the Ads tab.
// Ads whose analysis failed are left out, so they are picked up again on the next run.
const list = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const copyOnly = $prevNode.name === 'Analyze Ad Copy Only';
// Ad IDs are 15 to 17 digits. The leading apostrophe stores them as text, so Google Sheets
// does not round them like a number.
const asText = (id) => (id ? "'" + id : '');

const rows = [];
const errors = [];
for (const [i, item] of $input.all().entries()) {
  const a = item.json.output;
  const ad = $('Pick New Ads').itemMatching(i).json;
  if (item.json.error || !a || typeof a !== 'object') {
    errors.push(`${ad.page_name || ad.ad_id}: ${item.json.error || 'no analysis returned'}`);
    continue;
  }

  let basis = ad.analysis_basis;
  if (copyOnly) basis = ad.creative_url ? 'ad copy only (image download failed)' : 'ad copy only';

  rows.push({
    json: {
      analyzed_at: $now.toFormat('yyyy-MM-dd HH:mm'),
      search: ad.search,
      page_name: ad.page_name,
      ad_id: asText(ad.ad_id),
      status: ad.status,
      days_running: ad.days_running,
      start_date: ad.start_date,
      format: ad.format,
      platforms: ad.platforms,
      variants: ad.variants,
      score: a.score ?? '',
      hook: a.hook ?? '',
      angle: a.angle ?? '',
      offer: a.offer ?? '',
      call_to_action: a.call_to_action ?? '',
      target_audience: a.target_audience ?? '',
      emotional_triggers: list(a.emotional_triggers).join('; '),
      format_notes: a.format_notes ?? '',
      why_it_works: a.why_it_works ?? '',
      ideas_to_adapt: list(a.ideas_to_adapt).map((idea, n) => `${n + 1}. ${idea}`).join('\n'),
      headline: ad.headline,
      body: ad.body,
      cta: ad.cta,
      link_url: ad.link_url,
      ad_library_url: ad.ad_library_url,
      page_url: ad.page_url,
      creative_url: ad.creative_url,
      video_url: ad.video_url,
      analysis_basis: basis,
      collation_id: asText(ad.collation_id),
    },
    pairedItem: { item: i },
  });
}

if (!rows.length && errors.length) {
  throw new Error('The AI analysis failed for every ad. ' + errors.slice(0, 5).join(' | '));
}

return rows;
